  "Adds bodycams to the register and updates the ones already there, matched by serial number. Who has a bodycam right now never changes by import; that happens only when it is booked out or handed back.": "Yi engetela tikhamera ta miri eka rhijisitara naswona yi pfuxeta leti nga kona, hi ku pimanisa nomboro ya serial. Loyi a nga na khamera ya miri sweswi a nga cinci hi ku nghenisa; sweswo swi humelela ntsena loko yi humesiwa kumbe yi vuyisiwa.",
  "Adds firearms to the register and updates the ones already there, matched by serial number. Who holds a firearm right now never changes by import; that happens only when it is booked out or handed back.": "Yi engetela swibamu eka rhijisitara naswona yi pfuxeta leswi nga kona, hi ku pimanisa nomboro ya serial. Loyi a nga na xibamu sweswi a nga cinci hi ku nghenisa; sweswo swi humelela ntsena loko xi humesiwa kumbe xi vuyisiwa.",
  "Adds people to the staff register and updates the ones already there, matched by badge number. Nobody gets access: each person is invited afterwards and activates their own account.": "Yi engetela vanhu eka rhijisitara ya vatirhi naswona yi pfuxeta lava nga kona, hi ku pimanisa nomboro ya bheji. Ku hava loyi a kumaka mfikelelo: munhu un'wana na un'wana u rhambiwa endzhaku kutani a pfula akhawunti ya yena.",
  "Adds vehicles to the register and updates the ones already there, matched by department and unit number. A vehicle’s status never changes by import: one off the road stays off the road until fleet control returns it.": "Yi engetela mimovha eka rhijisitara naswona yi pfuxeta leyi nga kona, hi ku pimanisa ndzawulo na nomboro ya yuniti. Xiyimo xa movha a xi cinci hi ku nghenisa: lowu nga riki egondzweni wu tshama wu nga ri kona kukondza vulawuri bya mimovha byi wu vuyisa.",
  "Adjustment": "Ku lulamisa",
