  "EVIDENCE ({n})": "VUMBHONI ({n})",
  "Each call sign is a row: pick the member for it.": "Xikombiso xin'wana na xin'wana xo vitana i layini: hlawula xirho xa xona.",
  "Each call sign is one duty slot: where it patrols, its hours, its break and the rank it needs. Duty Allocation books staff onto these.": "Xikombiso xin'wana na xin'wana xo vitana i xivandla xin'we xa ntirho: laha xi patrolaka kona, tiawara ta xona, khefu ra xona na xiyimo lexi xi xi lavaka. Ku Avela Ntirho ku bhuka vatirhi eka swona.",
  "Each call sign with its area, hours and the rank it needs.": "Xikombiso xin'wana na xin'wana xo vitana na ndhawu ya xona, tiawara na xiyimo lexi xi xi lavaka.",
  "Each day's reports, by where they stand.": "Swiviko swa siku rin'wana na rin'wana, hi ku ya hi laha swi yimeke kona.",
  "Each link or code works once and expires after {invitationTtlHours} hours. Sending again cancels the old one.": "Xihlanganisi kumbe khodi yin'wana na yin'wana yi tirha kan'we naswona yi hela endzhaku ka tiawara ta {invitationTtlHours}. Ku rhumela nakambe ku herisa ya khale.",
  "Each member’s record as the old system kept it: numbers, rank, station, section, weekend group, contacts, LEO record and screen access.": "Rekhodo ya xirho xin'wana na xin'wana hilaha sistimi ya khale yi yi hlayiseke: tinomboro, xiyimo, xitichi, xiyenge, ntlawa wa mugqivela-sonto, vatihlanganisi, rekhodo ya LEO na ku nghena ka xikirini.",
  "Each patient and how bad they are": "Muvabyi un'wana na un'wana na leswaku u le xiyimweni xo biha ku fikela kwihi",
  "Each person gets their own invitation, as their confirmed role, by the route shown: email where HR gave an address, SMS where there is only a cellphone{value}, otherwise a printed code. Each link or code works once and expires after its set time.": "Munhu un'wana na un'wana u kuma xirhambo xa yena, tanihi ntirho wa yena lowu tiyisisiweke, hi ndlela leyi kombisiweke: imeyili laha HR yi nyikeke adirese, SMS laha ku nga na selfoni ntsena{value}, loko swi nga ri tano khodi leyi printiweke. Xihlanganisi kumbe khodi yin'wana na yin'wana yi tirha kan'we naswona yi hela endzhaku ka nkarhi wa yona lowu vekiweke.",
  "Each rule acts at most once per thing per threshold — a call that breaches its SLA raises one alert at each tier, not one every five minutes. Thresholds are stored per rule, so changing “escalate after 10 minutes” to 15 needs no deployment. Every change and every manual run is written to the audit trail with your name on it.": "Nawu wun'wana na wun'wana wu endla kan'we ntsena eka nchumu wun'wana na wun'wana eka ndzilakano wun'wana na wun'wana — riqingho leri tlulaka SLA ya rona ri pfuxa xilemukiso xin'we eka xiyimo xin'wana na xin'wana, ku nga ri xin'we timinete tin'wana na tin'wana ta ntlhanu. Mindzilakano yi hlayisiwa hi nawu wun'wana na wun'wana, hikwalaho ku cinca \"tlakusa endzhaku ka timinete ta 10\" ku va 15 a swi lavi ku nghenisiwa. Ku cinca kun'wana na kun'wana na ku endla kun'wana na kun'wana hi voko swi tsariwa eka mukondzo wa ku kambela na vito ra wena.",
  "Each service's identity — crest, colours and naming — as it appears across the platform, the responder app and printed reports.": "Vutitivisi bya vukorhokeri byin'wana na byin'wana — xikombiso, mivala na mavito — tani hi leswi swi humelelaka eka puratifomo hinkwayo, eka app ya vahlamuri na le ka swiviko leswi printiweke.",
