  "Emulators and simulators cannot register for push. Alerts still arrive while the app is open.": "Ti-emulator na ti-simulator a ti koti ku titsarisela switiviso. Swilemukiso swa ha fika loko app yi pfuriwile.",
  "En Route": "U le ndleleni",
