  "Enabled": "Swi pfuriwile",
  "Enabling a feature never grants a role anything the route matrix and row-level security would not — the two systems compose. Disabling one hides it everywhere and makes its server routes refuse, for this tenant only.": "Ku pfula nchumu a swi nyiki ntirho nchumu lowu matrix ya tindlela na vuhlayiseki bya xiyimo xa layini a swi nga ta wu pfumelela — mafambiselo lamambirhi ma tirha swin'we. Ku timela wun'we swi wu fihla hinkwako naswona swi endla leswaku tindlela ta wona ta sevha ti ala, eka muhiri lowu ntsena.",
