  "Evidence / portfolio ref": "Xikombo xa vumbhoni / xa potifoliyo",
  "Evidence file": "Fayili ya vumbhoni",
  "Evidence is captured by the crew working this incident.": "Vumbhoni byi hlengeletiwa hi ntlawa lowu tirhaka eka xiendlakalo lexi.",
  "Evidence log / SAP13 reference": "Rhekhodo ya vumbhoni / xikombo xa SAP13",
  "Example: HH, 1 to 300, 4 digits gives HH-0001 to HH-0300.": "Xikombiso: HH, 1 ku ya eka 300, tinomboro ta 4 ti nyika HH-0001 ku ya eka HH-0300.",
  "Excel (.xlsx) or CSV": "Excel (.xlsx) kumbe CSV",
  "Excel (.xlsx) or CSV with these columns: {join} (Method and Note are optional). Headings from most cashier and bank exports are recognised.": "Excel (.xlsx) kumbe CSV leyi nga na tikholomu leti: {join} (Ndlela na Xitsundzuxo a swi bohi). Tinhloko ku suka eka swirhumeriwa swo tala swa vakheyixara na mabangi ta tiviwa.",
