  "Filed reports are permanent and visible to dispatch and command.": "Swiviko leswi nghenisiweke i swa hilaha ku nga heriki naswona swi voniwa hi varhumeri na varhangeri.",
  "Filing report": "Ku nghenisiwa xiviko",
  "Filing resolves the incident. The report is permanent and visible to command and case managers.": "Ku nghenisa swi tlhantlha xiendlakalo. Xiviko i xa hilaha ku nga heriki naswona xi voniwa hi varhangeri na valawuri va milandzu.",
