  "For Fire & Rescue": "Eka Ndzilo na Ku Ponisa",
  "For a call that will never have a report: a hoax, a duplicate, or the caller cancelled.{value}": "Eka riqingho leri nga tshukiki ri va na xiviko: vuxisi, leri phindhiweke, kumbe muqingi u khansele.{value}",
  "For a notice issued in error. It stays on the register, marked cancelled, with your reason. Refund any money first.": "Eka xitiviso lexi humesiweke hi xihoxo. Xi tshama eka rejisitara, xi funghiwile tanihi lexi khanseriweke, ni xivangelo xa wena. Tlherisela mali yihi na yihi ku sungula.",
  "For a notice written in a notice book. Copy it exactly as written, with the printed notice number. Notices at the roadside are issued on the phone, where the infringer signs.": "Eka xitiviso lexi tsariweke ebukwini ya swiviso. Xi kopa hi ku ringanana hilaha xi tsariweke hakona, ni nomboro ya xitiviso leyi kandziyisiweke. Swiviso swa le gondzweni swi humesiwa eka riqingho, laha mutluri a sayinaka kona.",
  "For example towards the taxi rank": "Xikombiso, ku ya eka rhenki ya tithekisi",
  "For example: radio from a security guard": "Xikombiso: xiyanimoya xo huma eka murindzi wa vuhlayiseki",
  "For example: the caller rang back with the right address": "Xikombiso: muqingi u tlhele a qingha hi adirese leyi lulameke",
  "For leave on a form the member handed in, sick leave, or an absence such as AWOL. It is approved as captured and their duty in those dates is marked.": "Eka khefu eka fomo leyi xirho xi yi ngheniseke, khefu ra vuvabyi, kumbe ku nga vi kona ko fana na AWOL. Ri amukeriwa hilaha ri nghenisiweke naswona ntirho wa vona emasikwini wolawo wu funghiwa.",
  "For the whole organisation. Office-hours rotations skip them, and they are not counted as leave days.": "Ya nhlangano hinkwawo. Ku cincana ka tiawara ta hofisi ku ti tlula, naswona a ti hlayiwi tanihi masiku ya ku wisa.",
  "For their shift": "Ya xifti xa vona",
  "For you, your role, your department and everyone.": "Ya wena, ya ntirho wa wena, ya ndzawulo ya wena ni ya hinkwavo.",
