  "How HikTech is designed to work, agreed between eThekwini and the build team. Visible to administrators only.": "Ndlela leyi HikTech yi endleriweke ku tirha hayona, leyi pfumelelaniweke exikarhi ka eThekwini ni ntlawa wo aka. Yi voniwa hi vafambisi ntsena.",
