  "How often this rule is evaluated. The scheduler ticks every 5 minutes, so anything below that runs every tick.": "Hi ku tala ka kangani nawu lowu wu kamberiwaka. Muhleli u tirha timinete tin'wana ni tin'wana ta 5, hikwalaho xin'wana ni xin'wana lexi nga ehansi ka sweswo xi tirha nkarhi wun'wana ni wun'wana.",
