  "I am not drawing a firearm this shift (e.g. mine is not on the armoury register). This is recorded on my start-of-shift record.": "A ndzi teki xibamu eka shifiti leyi (xik. xa mina a xi kona eka rhijisitara ya vuhlayiselo bya swibamu). Leswi swi tsariwa eka rhekhodo ya mina ya ku sungula shifiti.",
  "I am not wearing a bodycam this shift. My reason is on my start-of-shift record and my supervisor sees it.": "A ndzi ambalanga bodycam eka shifiti leyi. Xivangelo xa mina xi le ka rhekhodo ya mina ya ku sungula shifiti naswona mulanguteri wa mina wa xi vona.",
  "I checked this ambulance and its stock myself, and the answers above are accurate.": "Ndzi kambele amhulanisi leyi na swibye swa yona hi mina n'wini, naswona tinhlamulo leti nga laha henhla ti lulamile.",
  "I confirm that I have physically inspected the above vehicle and that the information recorded is accurate to the best of my knowledge. Any faults noted must be reported to the immediate supervisor and recorded in the official pocket book.": "Ndzi tiyisisa leswaku ndzi kambele movha lowu nga laha henhla hi miri naswona leswaku vuxokoxoko lebyi tsariweke byi lulamile hilaha ndzi tivaka hakona. Swihoxo swihi na swihi leswi voniweke swi fanele ku vikiwa eka mulanguteri hi ku hatlisa no tsariwa ebukwini ya ximfumo ya xikhwama.",
  "I explained the court date, and that paying the admission of guilt is a conviction and may give a criminal record.": "Ndzi hlamuserile siku ra khoto, ni leswaku ku hakela ku amukela nandzu i ku avanyisiwa naswona swi nga nyika rhekhodo ya vugevenga.",
  "I explained the notice and the options: pay within 32 days for the discount, apply to pay in instalments (AARTO 04), or make a representation (AARTO 08).": "Ndzi hlamuserile xitiviso na swihlawulekisi: hakela endzeni ka masiku ya 32 ku kuma ntsongahato, kombela ku hakela hi swiphemu (AARTO 04), kumbe u endla xikombelo xa ku tihlamulela (AARTO 08).",
  "I have an activation code": "Ndzi na khodi yo sungula",
  "I have read the POPIA notice (version {POPIA_NOTICE_VERSION})": "Ndzi hlayile xitiviso xa POPIA (vhexeni {POPIA_NOTICE_VERSION})",
  "I have read this shift": "Ndzi hlayile shifiti leyi",
  "I know how your department works and I can read the live board your role can see. Ask me anything, or tell me what to do. I prepare it, and nothing changes until you confirm.": "Ndzi swi tiva leswaku ndzawulo ya wena yi tirha njhani naswona ndzi nga hlaya bodo leyi hanyaka leyi xiyimo xa wena xi yi vonaka. Ndzi vutisa xin'wana ni xin'wana, kumbe u ndzi byela leswi ndzi faneleke ku swi endla. Ndza swi lunghiselela, naswona a ku cinci nchumu ku fikela u tiyisisa.",
  "I know your shift, your calls, your leave and your kit. Ask me anything about your work, in your own words. I explain and show you where to go; you do the work.": "Ndzi yi tiva shifiti ya wena, swiqingho swa wena, ku wisa ka wena na swibye swa wena. Ndzi vutisa xin'wana ni xin'wana hi ntirho wa wena, hi marito ya wena. Ndza hlamusela naswona ndzi ku komba laha u faneleke ku ya kona; wena u endla ntirho.",
  "I personally completed these checks and confirm that the answers and any defects recorded are accurate.": "Ndzi endlile ku kambela loku hi mina n'wini naswona ndzi tiyisisa leswaku tinhlamulo na swihoxo leswi tsariweke swi lulamile.",
  "I will use HikTech only for official duties and keep my password private": "Ndzi ta tirhisa HikTech eka mintirho ya ximfumo ntsena naswona ndzi hlayisa phasiwedi ya mina yi ri xihundla",
  "I'm on scene — it has not changed": "Ndzi laha swi endlekeke kona — a swi cincanga",
  "I've restocked — check again": "Ndzi tatisile nakambe — kambela nakambe",
