  "Incidents routed to your department reach this phone even when the screen is locked. High and Critical incidents open a full-screen alert you must acknowledge.": "Swiendlakalo leswi rhumeriwaka eka ndzawulo ya wena swi fika eka foni leyi hambiloko xikirini xi lotleriwile. Swiendlakalo swa le Henhla na swa Xihatla swi pfula xilemukiso xa xikirini hinkwaxo lexi u faneleke ku xi amukela.",
