  "Isuzu": "Isuzu",
  "It gets the next CH- number; the arresting officer is you unless noted.": "Yi kuma nomboro leyi landzelaka ya CH-; ofisiri leyi khomaka i wena handle ka loko swi tsariwile.",
  "It gets the next DM- number; the assignee is alerted at once.": "Yi kuma nomboro leyi landzelaka ya DM-; loyi a averiweke u tivisiwa hi ku hatlisa.",
  "It gets the next SM- number. Service is recorded from the register below.": "Yi kuma nomboro leyi landzelaka ya SM-. Ku nyiketa ku tsariwa ku suka eka rhijisitara leyi nga laha hansi.",
  "It gets the next WA- number. Court and expiry as issued.": "Yi kuma nomboro leyi landzelaka ya WA-. Khoto na ku hela ka nkarhi tani hi loko swi nyikiwile.",
  "It goes for repair and your supervisor is told.": "Yi ya ku lulamisiwa naswona mulanguteri wa wena wa tivisiwa.",
  "It goes to the armourer for repair instead of back into service.": "Yi ya eka mulunghisi wa swibamu ku ya lulamisiwa ematshan'wini yo tlhelela entirhweni.",
  "It is alleged that…": "Ku vuriwa leswaku…",
  "It is held on this phone and sends automatically, ahead of everything else, the moment you have signal. Do not wait — SMS or call the control room now.": "Yi hlayisiwile eka foni leyi naswona yi rhumeriwa hi yoxe, ku nga si va hinkwaswo, hi nkarhi lowu u kumaka siginali. U nga rindzi — rhumela SMS kumbe u ringela control room sweswi.",
  "It is in the description, and follows your answers until you type.": "Yi le ka nhlamuselo, naswona yi landzela tinhlamulo ta wena ku fikela u tsala.",
  "It is waiting for signal and sends automatically.": "Yi rindzele siginali naswona yi rhumeriwa hi yoxe.",
  "It may belong to another officer, or the link is out of date.": "Yi nga va ya ofisiri yin'wana, kumbe linki a ya ha tirhi.",
  "It may have been closed or reassigned, or it is not for your department.": "Yi nga va yi pfariwile kumbe yi averiwile un'wana, kumbe a hi ya ndzawulo ya wena.",
