  "Official After-Action Reports. Filing one resolves the incident.": "Swiviko swa Ximfumo swa le Ndzhaku ka Ntirho. Ku rhumela xin'we swi ololoxa xiendlakalo.",
  "Official insignia belong to the municipality and its services, so the platform ships none — upload each department's real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department's colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.": "Mimfungho ya ximfumo i ya masipala ni mintirho ya wona, hikwalaho xitulu a xi yi tisi — layicha mfungho wa xiviri wa ndzawulo yin'wana ni yin'wana laha naswona wu humelela hinkwako hi ku hatlisa. Ku fikela hi nkarhi wolowo beji ya maletere yo sungula yi kombisiwa hi mivala ya ndzawulo yoleyo, hikwalaho a ku na nchumu lowu langutekaka wu nga hetisiwanga. PNG kumbe SVG leyi nga na xikhandziyelo lexi voningaka yi tirha kahle; swifaniso swa xikwere swi hlayeka kahle loko swi ri swintsongo.",
  "Official name": "Vito ra ximfumo",
