  "On parade, members sign on, sign off and sign for overtime on the paper.": "Eka phareyidi, swirho swi sayina loko swi sungula, loko swi heta ni hi nkarhi wo engetela ephepheni.",
  "On ramp/slipway": "Ndlela yo nghena eka gondzo lerikulu",
