  "On scene is marked by itself when you get there.": "Ku va ndhawini swi funghiwa hi swoxe loko u fika kona.",
  "On scene is marked when you arrive": "Ku va ndhawini swi funghiwa loko u fika",
  "On scene is set by the crew’s own phone reaching the scene. Click a strip to see the crew.": "Ku va ndhawini swi vekiwa hi foni ya ntlawa hi yoxe loko yi fika endhawini. Tshikelela layini ku vona ntlawa.",
