  "Once approved, {value} prints the activation slip and hands it over in person.": "Loko swi pfumeleriwile, {value} u kandziyisa phepha ro pfula a ri nyiketa hi voko.",
  "Once it has been cleaned, fleet control returns it to service.": "Loko yi basisiwile, vulawuri bya mimovha byi yi tlherisela entirhweni.",
  "One answer needs fixing": "Nhlamulo yin'we yi lava ku lulamisiwa",
  "One at a time. For many, use the import with the template.": "Yin'we hi nkarhi. Eka to tala, tirhisa ku nghenisa hi xikombiso.",
  "One at a time. For the whole armoury, use the import with the template.": "Xin'we hi nkarhi. Eka vuhlayiselo hinkwabyo bya matlhari, tirhisa ku nghenisa hi xikombiso.",
  "One at a time. For the whole fleet, use the import with the template.": "Wun'we hi nkarhi. Eka mimovha hinkwayo, tirhisa ku nghenisa hi xikombiso.",
  "One person": "Munhu un'we",
  "One thing is missing:": "Ku na nchumu wun'we lowu pfumalekaka:",
  "Only Staff Maintenance and the member can see this.": "I Nhlayiso wa Vatirhi na xirho ntsena lava nga vonaka leswi.",
  "Only a translator for this language approves. You can save drafts.": "I muhundzuluxi wa ririmi leri ntsena loyi a pfumelelaka. U nga hlayisa tidrafti.",
  "Only approved translations are shown on the screens. Everything else shows in English.": "Tindzimi leti hundzuluxiweke leti pfumeleriweke ntsena ti kombisiwa eka swikirini. Swin'wana hinkwaswo swi kombisiwa hi Xinghezi.",
  "Only fines I issued": "Magandlo lawa ndzi ma nyikeke ntsena",
  "Only if there is no emergency. Why?": "Ntsena loko ku nga ri na xihatla. Hikokwalaho ka yini?",
  "Only me": "Mina ntsena",
  "Only officers who went on duty in the app after today's start of shift are listed. Distance is straight-line from their last GPS heartbeat; ETA assumes {speedKmh} km/h with a {roadFactor}× road factor (Admin → Operations Settings).": "Ku nxaxameriwa ntsena vaofisiri lava ngheneke entirhweni eka app endzhaku ka ku sungula ka shifiti ya namuntlha. Mpfhuka i layini yo olova ku suka eka siginali ya vona yo hetelela ya GPS; ETA yi teka {speedKmh} km/h na xiphemu xa gondzo xa {roadFactor}× (Admin → Swilulamiso swa Ntirho).",
  "Only one patient": "Muvabyi un'we ntsena",
  "Only someone senior to the member, in their department, can approve. Nobody approves their own.": "I munhu loyi a nga ehenhla ka xirho ntsena, eka ndzawulo ya xona, loyi a nga pfumelelaka. A ku na loyi a tipfumelelaka.",
  "Only the firefighter leading this incident files its fire report.": "I mutimi wa ndzilo loyi a rhangelaka xiendlakalo lexi ntsena loyi a rhumelaka xiviko xa xona xa ndzilo.",
  "Only the lead officer on this incident can file its report.": "I ofisiri loyi a rhangelaka xiendlakalo lexi ntsena loyi a nga rhumelaka xiviko xa xona.",
  "Only the officer leading this incident files its post-mortem.": "I ofisiri loyi a rhangelaka xiendlakalo lexi ntsena loyi a rhumelaka nxopaxopo wa xona wa le ndzhaku.",
  "Only the paramedic leading this incident files its patient report.": "I paramediki loyi a rhangelaka xiendlakalo lexi ntsena loyi a rhumelaka xiviko xa xona xa muvabyi.",
  "Only the person who logged {number}, or the control room, can finish it.": "I munhu loyi a tsaleke {number} ntsena, kumbe kamara ya vulawuri, loyi a nga yi hetisaka.",
  "Only the {desks} dispatch desk receives this call.": "I tafula ro rhumela ra {desks} ntsena leri amukelaka riqingho leri.",
