  "Road traffic offences carry the AARTO Schedule 3 charge code and penalty; by-law offences carry the by-law section and the admission of guilt amount. Enter both from the official schedules, then verify. Changing a verified code or amount takes the verification off until someone checks it again.": "Milandzu ya gondzo yi khome khodi ya nandzu ya AARTO Schedule 3 na gandlo; milandzu ya nawu wa masipala yi khome xiyenge xa nawu na mali yo pfumela nandzu. Nghenisa swimbirhi ku suka eka minxaxamelo ya ximfumo, kutani u tiyisisa. Ku cinca khodi kumbe mali leyi tiyisisiweke swi susa ku tiyisisa ku fikela munhu a swi kambela nakambe.",
  "Road traffic offences on AARTO 01 notices; by-law offences on Section 56 (offender present) or Section 341 (unattended vehicle) notices. Every charge has its own FN- number, and a served notice can never be edited or deleted — only cancelled, with a reason.": "Milandzu ya gondzo eka switiviso swa AARTO 01; milandzu ya nawu wa masipala eka switiviso swa Xiyenge 56 (mutlula-nawu u kona) kumbe Xiyenge 341 (movha lowu nga langutiwiki). Nandzu wun'wana ni wun'wana wu na nomboro ya wona ya FN-, naswona xitiviso lexi nyikeriweke a xi nge pfuki xi cinciwile kumbe xi suriwa — xi nga khanseriwa ntsena, hi xivangelo.",
