  "Updates by itself as crews move. A Fire incident is resolved when its fire report is filed.": "Swi tipfuxeta hi swoxe loko mintlawa yi famba. Xiendlakalo xa ndzilo xi ololoxiwa loko xiviko xa xona xa ndzilo xi rhumeriwa.",
  "Updates you captured are stored on this phone and send themselves as soon as there is signal.": "Mimpfuxeto leyi u yi tekeke yi hlayisiwa eka foni leyi naswona yi tirhumela hi ku hatlisa loko ku ri na siginali.",
  "Upholstery": "Swifunengeto swa swiluvelo",
  "Upload": "Layicha",
  "Upload evidence": "Layicha vumbhoni",
  "Upload the day’s receipts from the cashier or the bank. Each row is matched to a fine by its FN- number or its notice number, and recorded with the date on the receipt — so a payment made inside the 32 days keeps the AARTO discount even when it is captured later. A receipt already on a fine is skipped, so importing the same file twice records nothing twice.": "Layicha tirhisiti ta siku ku suka eka mukheshiya kumbe ebangi. Layini yin'wana ni yin'wana yi fambelanisiwa na gandlo hi nomboro ya rona ya FN- kumbe nomboro ya xitiviso xa rona, naswona yi tsariwa na siku leri nga eka rhisiti — hikwalaho hakelo leyi endliweke endzeni ka masiku ya 32 yi hlayisa ku hunguta ka AARTO hambi yi nghenisiwe endzhaku. Rhisiti leyi se yi nga eka gandlo ya tluriwa, hikwalaho ku nghenisa fayili leyi fanaka kambirhi a ku tsali nchumu kambirhi.",
  "Urban 1-way": "Edorobeni ndlela ya tlhelo rin'we",
  "Urban 2-way": "Edorobeni tindlela timbirhi",
