  "What is sent to you, your role, your department and everyone lands here. High and Critical incidents also open a full-screen alert you have to acknowledge.": "Leswi rhumeriwaka eka wena, eka xiave xa wena, eka ndzawulo ya wena na eka hinkwavo swi fika laha. Swiendlakalo swa le Henhla na swa Nkoka ngopfu swi pfula nakambe xitsundzuxo xa xikirini hinkwaxo lexi u faneleke ku xi amukela.",
  "What is switched on for {value}. Changes apply to every user in the organisation, take effect on their next page load — the responder app follows within moments over realtime — and are written to the audit trail with your name.": "Leswi pfuriweke eka {value}. Ku cinca ku tirha eka vatirhisi hinkwavo eka nhlangano, ku sungula loko va layicha tluka leri landzelaka — app ya vahlamuri yi landzela hi tisekoni — naswona ku tsariwa eka mukondzo wa nkambelo hi vito ra wena.",
