  "Your role cannot change this account.{value}": "Xiave xa wena a xi nge cinci akhawunti leyi.{value}",
  "Your saved draft has been restored. Verify every answer before filing.": "Drafti ya wena leyi hlayisiweke yi tlheriseriwile. Tiyisisa nhlamulo yin'wana ni yin'wana u nga si rhumela.",
  "Your saved draft has been restored. Verify every answer before signing.": "Drafti ya wena leyi hlayisiweke yi tlheriseriwile. Tiyisisa nhlamulo yin'wana ni yin'wana u nga si sayina.",
  "Your session has expired — sign in again.": "Ku nghena ka wena ku herile nkarhi — nghena nakambe.",
  "Your session is safe. Tap below to retry — if it keeps happening, show this screen to your system administrator and fall back to radio.": "Ku nghena ka wena ku hlayisekile. Tshikelela laha hansi ku ringeta nakambe — loko swi ya emahlweni swi humelela, kombisa mulawuri wa sisitimi xikirini lexi kutani u tirhisa radiyo.",
