  "Your {describe} for {value}'s {describe2}": "{describe} ya wena ya {describe2} ya {value}",
  "Your {filedList} are signed and filed for today. Export a copy for your records, then continue to your dashboard.": "{filedList} ya wena yi sayiniwile naswona yi rhumeriwile namuntlha. Humesa khopi ya tirhekhodo ta wena, kutani u ya emahlweni eka dexibodo ya wena.",
  "Your {nameOf} on {dayLabel}": "{nameOf} ya wena hi {dayLabel}",
