  "and sanitise it for release. Remove names, exact addresses and investigative details.": "kutani u yi basisa leswaku yi humesiwa. Susa mavito, tiadirese leti kongomeke na vuxokoxoko bya ndzavisiso.",
  "and your supervisor has been told. Choose another one, or tick No bodycam today, to complete your start of shift.": "naswona mulanguteri wa wena u byeriwile. Hlawula yin'wana, kumbe u funghi A ku na bodycam namuntlha, ku heta ku sungula ka shifiti ya wena.",
